class Solution {
public:
    string mergeCharacters(string s,int k) {
        string ans;
        int last[26];fill(last,last+26,-1000000000);
        for(char c:s){
            int x=c-'a',pos=ans.size();
            if(pos-last[x]<=k)continue;
            last[x]=pos;ans.push_back(c);
        }
        return ans;
    }
};
